private let fixtureStart = ISO8601DateFormatter().date(from: "2026-10-13T08:00:00Z")!

@Test func parsesRealMETResponse() throws {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC")!
    let forecast = try #require(WeatherForecast.parse(Data(fixture.utf8), now: fixtureStart, calendar: calendar))
    #expect(forecast.temperature > -60 && forecast.temperature < 60)
    #expect(forecast.symbol != nil)
    #expect(forecast.hours.count == 12)
    #expect(!forecast.days.isEmpty)
    for day in forecast.days { #expect(day.low <= day.high) }
}

@Test func garbageIsRejected() {
    #expect(WeatherForecast.parse(Data("not json".utf8)) == nil)
}

@Test func symbolsMapToSFSymbols() {
    #expect(WeatherSymbol.sfSymbol(for: "clearsky_day") == "sun.max.fill")
    #expect(WeatherSymbol.sfSymbol(for: "clearsky_night") == "moon.stars.fill")
    #expect(WeatherSymbol.sfSymbol(for: "heavyrain") == "cloud.heavyrain.fill")
    #expect(WeatherSymbol.sfSymbol(for: "lightsnowshowers_day") == "cloud.snow.fill")
    #expect(WeatherSymbol.sfSymbol(for: "rainandthunder") == "cloud.bolt.rain.fill")
    #expect(WeatherSymbol.description(for: "partlycloudy_day") == "Partly cloudy")
    #expect(WeatherSymbol.description(for: "lightrainshowers_day") == "Light rain showers")
}

@Test func windChillOnlyWhenColdAndWindy() {
    #expect(WeatherForecast.feelsLike(temperature: 25, windSpeed: 10) == 25)
    #expect(WeatherForecast.feelsLike(temperature: 0, windSpeed: 0.5) == 0)
    #expect(WeatherForecast.feelsLike(temperature: 0, windSpeed: 8) < 0)
}
